    public boolean estSimple() {
        for(Integer sommetI : mapAretes.keySet()){
            for (Integer sommetJ : mapAretes.keySet()){
                if (!Objects.equals(sommetI, sommetJ)){
                    Arete aIJ=new Arete(sommetI,sommetJ);
