    public boolean estComplet() {
        if(!estSimple()){
            return false;
        }
        for(int i = 0; i < mapAretes.size(); i++){
            for (int j = 0; j < mapAretes.size(); j++){
                Arete a = new Arete(i,j);
                Arete a2 = new Arete(j,i);
                if (i != j && !existeArete(a) && !existeArete(a2)) return false;
            }
        }
        return true;
