     * On considère que dans le cas où G n'a que 2 sommets {i,j}, et 2 arêtes parallèles {i,j}, alors G n'est PAS un cycle.
     * On considère que le graphe vide est un cycle.
     */
    public boolean estUnCycle() {
        if(!estUneChaine()){
            return false;
        }
        for (HashSet<Arete> aretes : mapAretes.values()) {
            if (aretes.size() != 2) return false;
        }
        return true;
    }


    public boolean estUneForet() {
        Set<Set<Integer>> classesConnexites = getEnsembleClassesConnexite();
        for(Set<Integer> set : classesConnexites)
            if (new Graphe(this, set).estUnCycle()) return false;
        return true;
    }

    public Set<Integer> getClasseConnexite(int v) {
        Set<Integer> sommetsVisites = new HashSet<>();
        Queue<Integer> sommetsAVisiter = new PriorityQueue<>();
        if(mapAretes.containsKey(v)) sommetsAVisiter.add(v);
        while (!sommetsAVisiter.isEmpty()) {
            int currentSommet = sommetsAVisiter.poll();
            if (!sommetsVisites.contains(currentSommet)) {
                sommetsVisites.add(currentSommet);
                sommetsAVisiter.addAll(getVoisins(currentSommet));
            }
        }
        return sommetsVisites;
    }

    public Set<Set<Integer>> getEnsembleClassesConnexite() {
        Set<Set<Integer>> setTotal=new HashSet<>();
        for(Integer i:mapAretes.keySet()){
