        int totalConnexe = getEnsembleClassesConnexite().size();
        supprimerArete(a);
        if(totalConnexe != getEnsembleClassesConnexite().size()){
            ajouterArete(a);
            return false;
        }
        ajouterArete(a);
        return true;
    }

